import { useState, useEffect } from 'react';
import { ingredientsService, dishesService } from '../firebase/dataService';
import { Ingredient, Dish } from '../types';

export const useFirebase = () => {
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [dishes, setDishes] = useState<Dish[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    console.log('Firebase hook initialized');
    
    // Подписка на изменения ингредиентов
    const unsubscribeIngredients = ingredientsService.subscribe((data) => {
      console.log('Ingredients loaded:', data);
      setIngredients(data);
      setLoading(false);
      setError(null); // Очищаем ошибки при успешной загрузке
    });

    // Подписка на изменения блюд
    const unsubscribeDishes = dishesService.subscribe((data) => {
      console.log('Dishes loaded:', data);
      setDishes(data);
      setLoading(false);
      setError(null); // Очищаем ошибки при успешной загрузке
    });

    // Очистка подписок при размонтировании
    return () => {
      unsubscribeIngredients();
      unsubscribeDishes();
    };
  }, []);

  // Принудительная перезагрузка данных
  const forceRefresh = async () => {
    try {
      const freshIngredients = await ingredientsService.getAll();
      const freshDishes = await dishesService.getAll();
      setIngredients(freshIngredients);
      setDishes(freshDishes);
      console.log('Force refresh completed');
    } catch (err) {
      console.error('Force refresh error:', err);
    }
  };

  // Функции для работы с ингредиентами
  const addIngredient = async (ingredient: Omit<Ingredient, 'id'>) => {
    try {
      setError(null);
      await ingredientsService.add(ingredient);
    } catch (err: any) {
      console.error('Error adding ingredient:', err);
      setError(`Ошибка при добавлении ингредиента: ${err.message}`);
    }
  };

  const updateIngredient = async (id: string, ingredient: Partial<Ingredient>) => {
    try {
      setError(null);
      await ingredientsService.update(id, ingredient);
    } catch (err: any) {
      console.error('Error updating ingredient:', err);
      setError(`Ошибка при обновлении ингредиента: ${err.message}`);
    }
  };

  const deleteIngredient = async (id: string) => {
    try {
      setError(null);
      await ingredientsService.delete(id);
      console.log('Ingredient deleted successfully:', id);
      
      // Принудительно обновляем состояние после удаления
      setIngredients(prev => prev.filter(ingredient => ingredient.id !== id));
      
      // Принудительно перезагружаем данные из Firebase несколько раз
      setTimeout(async () => {
        try {
          const freshData = await ingredientsService.getAll();
          console.log('Fresh data after deletion:', freshData);
          setIngredients(freshData);
        } catch (err) {
          console.error('Error refreshing data:', err);
        }
      }, 500);
      
      setTimeout(async () => {
        try {
          const freshData = await ingredientsService.getAll();
          console.log('Fresh data after 2 seconds:', freshData);
          setIngredients(freshData);
        } catch (err) {
          console.error('Error refreshing data:', err);
        }
      }, 2000);
      
      // Принудительно перезагружаем через 5 секунд
      setTimeout(async () => {
        try {
          const freshData = await ingredientsService.getAll();
          console.log('Fresh data after 5 seconds:', freshData);
          setIngredients(freshData);
        } catch (err) {
          console.error('Error refreshing data:', err);
        }
      }, 5000);
    } catch (err: any) {
      console.error('Error deleting ingredient:', err);
      // Не перебрасываем ошибку, так как удаление может быть успешным локально
      setIngredients(prev => prev.filter(ingredient => ingredient.id !== id));
    }
  };

  // Функции для работы с блюдами
  const addDish = async (dish: Omit<Dish, 'id'>) => {
    try {
      setError(null);
      await dishesService.add(dish);
    } catch (err: any) {
      console.error('Error adding dish:', err);
      setError(`Ошибка при добавлении блюда: ${err.message}`);
    }
  };

  const updateDish = async (id: string, dish: Partial<Dish>) => {
    try {
      setError(null);
      await dishesService.update(id, dish);
    } catch (err: any) {
      console.error('Error updating dish:', err);
      setError(`Ошибка при обновлении блюда: ${err.message}`);
    }
  };

  const deleteDish = async (id: string) => {
    try {
      setError(null);
      await dishesService.delete(id);
      console.log('Dish deleted successfully:', id);
      
      // Принудительно обновляем состояние после удаления
      setDishes(prev => prev.filter(dish => dish.id !== id));
      
      // Принудительно перезагружаем данные из Firebase
      setTimeout(async () => {
        try {
          const freshData = await dishesService.getAll();
          setDishes(freshData);
        } catch (err) {
          console.error('Error refreshing data:', err);
        }
      }, 1000);
    } catch (err: any) {
      console.error('Error deleting dish:', err);
      // Не перебрасываем ошибку, так как удаление может быть успешным локально
      setDishes(prev => prev.filter(dish => dish.id !== id));
    }
  };

  return {
    ingredients,
    dishes,
    loading,
    error,
    addIngredient,
    updateIngredient,
    deleteIngredient,
    addDish,
    updateDish,
    deleteDish,
    forceRefresh
  };
};
