import React, { useState } from 'react';
import {
  Container,
  Typography,
  Box,
  Button,
  Card,
  CardContent,
  CardActions,
  Tabs,
  Tab,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  Chip,
  Alert,
  Snackbar
} from '@mui/material';

import {
  Add as AddIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  PictureAsPdf as PdfIcon,
  Visibility as ViewIcon
} from '@mui/icons-material';
import { IngredientForm } from './components/IngredientForm';
import { DishForm } from './components/DishForm';
import { TechnicalCard } from './components/TechnicalCard';
import { SearchBar } from './components/SearchBar';
import { ShoppingList } from './components/ShoppingList';
import { useFirebase } from './hooks/useFirebase';
import { filterIngredients, filterDishes, sortDishes } from './utils/filtering';
import { calculateDishYield } from './utils/calculations';

import { Ingredient, Dish } from './types';

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`simple-tabpanel-${index}`}
      aria-labelledby={`simple-tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
    </div>
  );
}

function App() {
  const {
    ingredients,
    dishes,
    loading,
    error,
    addIngredient,
    updateIngredient,
    deleteIngredient,
    addDish,
    updateDish,
    deleteDish,
    forceRefresh
  } = useFirebase();
  const [tabValue, setTabValue] = useState(0);
  const [ingredientFormOpen, setIngredientFormOpen] = useState(false);
  const [dishFormOpen, setDishFormOpen] = useState(false);
  const [selectedIngredient, setSelectedIngredient] = useState<Ingredient | undefined>();
  const [selectedDish, setSelectedDish] = useState<Dish | undefined>();
  const [viewDish, setViewDish] = useState<Dish | undefined>();
  const [technicalCardOpen, setTechnicalCardOpen] = useState(false);
  
  // Состояние для поиска и фильтрации
  const [ingredientSearchTerm, setIngredientSearchTerm] = useState('');
  const [dishSearchTerm, setDishSearchTerm] = useState('');
  const [dishCategoryFilter, setDishCategoryFilter] = useState('');
  const [dishSortBy, setDishSortBy] = useState<'name' | 'category' | 'cost' | 'date'>('name');
  const [dishSortOrder, setDishSortOrder] = useState<'asc' | 'desc'>('asc');
  
  // Состояние для подтверждения удаления
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<{ type: 'ingredient' | 'dish', id: string, name: string } | null>(null);
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMessage, setSnackbarMessage] = useState('');
  const [snackbarSeverity, setSnackbarSeverity] = useState<'success' | 'error'>('success');

    const handleIngredientSave = async (ingredient: Ingredient) => {
    if (selectedIngredient) {
      // При обновлении передаем только изменяемые поля, исключая id
      const { id, ...updateData } = ingredient;
      await updateIngredient(id, updateData);
    } else {
      // При создании исключаем id, так как он будет создан Firebase
      const { id, ...createData } = ingredient;
      await addIngredient(createData);
    }
    setSelectedIngredient(undefined);
  };

  const handleDishSave = async (dish: Dish) => {
    if (selectedDish) {
      // При обновлении сохраняем id отдельно
      const { id, ...updateData } = dish;
      await updateDish(selectedDish.id, updateData);
    } else {
      // При создании исключаем id, так как он будет создан Firebase
      const { id, ...createData } = dish;
      await addDish(createData);
    }
    setSelectedDish(undefined);
  };

  const handleIngredientDelete = async (id: string) => {
    try {
      await deleteIngredient(id);
      setSnackbarMessage('Ингредиент успешно удален');
      setSnackbarSeverity('success');
      setSnackbarOpen(true);
    } catch (error: any) {
      console.error('Delete ingredient error:', error);
      setSnackbarMessage(`Ошибка при удалении ингредиента: ${error.message}`);
      setSnackbarSeverity('error');
      setSnackbarOpen(true);
    }
  };

  const handleDishDelete = async (id: string) => {
    try {
      await deleteDish(id);
      setSnackbarMessage('Блюдо успешно удалено');
      setSnackbarSeverity('success');
      setSnackbarOpen(true);
    } catch (error: any) {
      console.error('Delete dish error:', error);
      setSnackbarMessage(`Ошибка при удалении блюда: ${error.message}`);
      setSnackbarSeverity('error');
      setSnackbarOpen(true);
    }
  };

  const confirmDelete = (type: 'ingredient' | 'dish', id: string, name: string) => {
    setItemToDelete({ type, id, name });
    setDeleteDialogOpen(true);
  };

  const handleConfirmDelete = async () => {
    if (!itemToDelete) return;
    
    try {
      if (itemToDelete.type === 'ingredient') {
        await handleIngredientDelete(itemToDelete.id);
      } else {
        await handleDishDelete(itemToDelete.id);
      }
      setDeleteDialogOpen(false);
      setItemToDelete(null);
    } catch (error) {
      console.error('Delete error:', error);
    }
  };

  const handleExportPDF = async (dish: Dish) => {
    setViewDish(dish);
    setTechnicalCardOpen(true);
  };

  // Получение уникальных категорий блюд
  const dishCategories = Array.from(new Set(dishes.map(dish => dish.category)));

  // Фильтрация и сортировка данных
  const filteredIngredients = filterIngredients(ingredients, ingredientSearchTerm);
  const filteredDishes = filterDishes(dishes, dishSearchTerm, dishCategoryFilter);
  const sortedDishes = sortDishes(filteredDishes, dishSortBy, dishSortOrder);

  if (loading) {
    return (
      <Container maxWidth="lg" sx={{ py: 4, textAlign: 'center' }}>
        <Typography variant="h4" gutterBottom>
          Загрузка данных...
        </Typography>
      </Container>
    );
  }

  if (error) {
    return (
      <Container maxWidth="lg" sx={{ py: 4, textAlign: 'center' }}>
        <Typography variant="h4" color="error" gutterBottom>
          Ошибка: {error}
        </Typography>
      </Container>
    );
  }

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      <Typography variant="h3" component="h1" gutterBottom align="center">
        Система технических карт блюд
      </Typography>

      <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
        <Tabs value={tabValue} onChange={(_, newValue) => setTabValue(newValue)}>
          <Tab label="Ингредиенты" />
          <Tab label="Блюда" />
          <Tab label="Список покупок" />
        </Tabs>
      </Box>

      <TabPanel value={tabValue} index={0}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 3 }}>
          <Typography variant="h5">Ингредиенты</Typography>
          <Box sx={{ display: 'flex', gap: 2 }}>
            <Button
              variant="outlined"
              onClick={forceRefresh}
            >
              Обновить
            </Button>
            <Button
              variant="contained"
              startIcon={<AddIcon />}
              onClick={() => setIngredientFormOpen(true)}
            >
              Добавить ингредиент
            </Button>
          </Box>
        </Box>

        <SearchBar
          searchTerm={ingredientSearchTerm}
          onSearchChange={setIngredientSearchTerm}
          categoryFilter=""
          onCategoryChange={() => {}}
          categories={[]}
          placeholder="Поиск ингредиентов..."
        />

        <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: 3 }}>
          {filteredIngredients.map(ingredient => (
            <Card key={ingredient.id}>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  {ingredient.name}
                </Typography>
                                  <Typography variant="body2" color="text.secondary">
                    Цена: {ingredient.pricePerUnit} zł/{ingredient.unit} (брутто)
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    Отход: {ingredient.wastePercentage}%
                  </Typography>
                <Typography variant="body2">
                  БЖУ: {ingredient.proteins}/{ingredient.fats}/{ingredient.carbohydrates} г
                </Typography>
                <Typography variant="body2">
                  Калории: {ingredient.calories} ккал
                </Typography>
                {ingredient.allergens.length > 0 && (
                  <Box sx={{ mt: 1 }}>
                    {ingredient.allergens.map(allergen => (
                      <Chip key={allergen} label={allergen} size="small" sx={{ mr: 0.5, mb: 0.5 }} />
                    ))}
                  </Box>
                )}
              </CardContent>
              <CardActions>
                <IconButton
                  size="small"
                  onClick={() => {
                    setSelectedIngredient(ingredient);
                    setIngredientFormOpen(true);
                  }}
                >
                  <EditIcon />
                </IconButton>
                <IconButton
                  size="small"
                  onClick={() => confirmDelete('ingredient', ingredient.id, ingredient.name)}
                >
                  <DeleteIcon />
                </IconButton>
              </CardActions>
            </Card>
          ))}
        </Box>
      </TabPanel>

      <TabPanel value={tabValue} index={1}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 3 }}>
          <Typography variant="h5">Блюда</Typography>
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => setDishFormOpen(true)}
            disabled={ingredients.length === 0}
          >
            Создать блюдо
          </Button>
        </Box>

        <SearchBar
          searchTerm={dishSearchTerm}
          onSearchChange={setDishSearchTerm}
          categoryFilter={dishCategoryFilter}
          onCategoryChange={setDishCategoryFilter}
          categories={dishCategories}
          placeholder="Поиск блюд..."
        />

        <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: 3 }}>
          {sortedDishes.map(dish => (
            <Card key={dish.id}>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  {dish.name}
                </Typography>
                <Typography variant="body2" color="text.secondary" gutterBottom>
                  {dish.description}
                </Typography>
                <Typography variant="body2">
                  Категория: {dish.category}
                </Typography>
                <Typography variant="body2">
                  Выход: {(() => {
                    const calculatedYield = calculateDishYield(dish.ingredients);
                    return `${calculatedYield.yield} ${calculatedYield.yieldUnit}`;
                  })()}
                </Typography>
                <Typography variant="body2">
                  Время: {dish.cookingTime} мин
                </Typography>
              </CardContent>
              <CardActions>
                <IconButton
                  size="small"
                  onClick={() => {
                    setViewDish(dish);
                    setTechnicalCardOpen(true);
                  }}
                >
                  <ViewIcon />
                </IconButton>
                <IconButton
                  size="small"
                  onClick={() => handleExportPDF(dish)}
                >
                  <PdfIcon />
                </IconButton>
                <IconButton
                  size="small"
                  onClick={() => {
                    setSelectedDish(dish);
                    setDishFormOpen(true);
                  }}
                >
                  <EditIcon />
                </IconButton>
                <IconButton
                  size="small"
                  onClick={() => confirmDelete('dish', dish.id, dish.name)}
                >
                  <DeleteIcon />
                </IconButton>
              </CardActions>
            </Card>
          ))}
        </Box>
      </TabPanel>

      <TabPanel value={tabValue} index={2}>
        <ShoppingList dishes={dishes} ingredients={ingredients} />
      </TabPanel>

      <IngredientForm
        open={ingredientFormOpen}
        onClose={() => {
          setIngredientFormOpen(false);
          setSelectedIngredient(undefined);
        }}
        onSave={handleIngredientSave}
        ingredient={selectedIngredient}
      />

      <DishForm
        open={dishFormOpen}
        onClose={() => {
          setDishFormOpen(false);
          setSelectedDish(undefined);
        }}
        onSave={handleDishSave}
        dish={selectedDish}
        ingredients={ingredients}
      />

      <Dialog
        open={technicalCardOpen}
        onClose={() => setTechnicalCardOpen(false)}
        maxWidth="md"
        fullWidth
      >
        {viewDish && (
          <div id="technical-card">
            <TechnicalCard dish={viewDish} />
          </div>
        )}
      </Dialog>

      {/* Диалог подтверждения удаления */}
      <Dialog open={deleteDialogOpen} onClose={() => setDeleteDialogOpen(false)}>
        <DialogTitle>Подтверждение удаления</DialogTitle>
        <DialogContent>
          <Typography>
            Вы уверены, что хотите удалить "{itemToDelete?.name}"?
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteDialogOpen(false)}>Отмена</Button>
          <Button onClick={handleConfirmDelete} color="error" variant="contained">
            Удалить
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar для уведомлений */}
      <Snackbar
        open={snackbarOpen}
        autoHideDuration={6000}
        onClose={() => setSnackbarOpen(false)}
      >
        <Alert
          onClose={() => setSnackbarOpen(false)}
          severity={snackbarSeverity}
          sx={{ width: '100%' }}
        >
          {snackbarMessage}
        </Alert>
      </Snackbar>
    </Container>
  );
}

export default App;
