import React, { useState, useMemo } from 'react';
import {
  Paper,
  Typography,
  Box,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Checkbox,
  Button,
  Chip,
  Divider,
  IconButton,
  Tooltip
} from '@mui/material';
import { Delete as DeleteIcon, Print as PrintIcon } from '@mui/icons-material';
import { Dish, Ingredient } from '../types';

interface ShoppingListProps {
  dishes: Dish[];
  ingredients: Ingredient[];
}

interface ShoppingItem {
  ingredientId: string;
  ingredient: Ingredient;
  totalQuantity: number;
  unit: string;
  totalCost: number;
  dishes: string[]; // Названия блюд, где используется этот ингредиент
}

export const ShoppingList: React.FC<ShoppingListProps> = ({ dishes, ingredients }) => {
  const [selectedDishes, setSelectedDishes] = useState<string[]>([]);
  const [checkedItems, setCheckedItems] = useState<Set<string>>(new Set());

  // Генерация списка покупок
  const shoppingList = useMemo(() => {
    if (selectedDishes.length === 0) return [];

    const itemMap = new Map<string, ShoppingItem>();

    selectedDishes.forEach(dishId => {
      const dish = dishes.find(d => d.id === dishId);
      if (!dish) return;

      dish.ingredients.forEach(recipeIngredient => {
        if (!recipeIngredient.ingredient) return;

        const ingredientId = recipeIngredient.ingredientId;
        const existingItem = itemMap.get(ingredientId);

        if (existingItem) {
          existingItem.totalQuantity += recipeIngredient.quantity;
          existingItem.totalCost += recipeIngredient.quantity * recipeIngredient.ingredient.pricePerUnit;
          if (!existingItem.dishes.includes(dish.name)) {
            existingItem.dishes.push(dish.name);
          }
        } else {
          itemMap.set(ingredientId, {
            ingredientId,
            ingredient: recipeIngredient.ingredient,
            totalQuantity: recipeIngredient.quantity,
            unit: recipeIngredient.ingredient.unit,
            totalCost: recipeIngredient.quantity * recipeIngredient.ingredient.pricePerUnit,
            dishes: [dish.name]
          });
        }
      });
    });

    return Array.from(itemMap.values()).sort((a, b) => a.ingredient.name.localeCompare(b.ingredient.name));
  }, [selectedDishes, dishes]);

  const handleDishToggle = (dishId: string) => {
    setSelectedDishes(prev => 
      prev.includes(dishId) 
        ? prev.filter(id => id !== dishId)
        : [...prev, dishId]
    );
  };

  const handleItemToggle = (ingredientId: string) => {
    setCheckedItems(prev => {
      const newSet = new Set(prev);
      if (newSet.has(ingredientId)) {
        newSet.delete(ingredientId);
      } else {
        newSet.add(ingredientId);
      }
      return newSet;
    });
  };

  const handlePrint = () => {
    const printContent = `
      СПИСОК ПОКУПОК
      Дата: ${new Date().toLocaleDateString('ru-RU')}
      
      Выбранные блюда:
      ${selectedDishes.map(id => dishes.find(d => d.id === id)?.name).filter(Boolean).join(', ')}
      
      Ингредиенты:
      ${shoppingList.map(item => 
        `${item.ingredient.name} - ${item.totalQuantity} ${item.unit} (${item.totalCost.toFixed(2)} zł)`
      ).join('\n')}
      
      Общая стоимость: ${shoppingList.reduce((sum, item) => sum + item.totalCost, 0).toFixed(2)} zł
    `;

    const printWindow = window.open('', '_blank');
    if (printWindow) {
      printWindow.document.write(`
        <html>
          <head>
            <title>Список покупок</title>
            <style>
              body { font-family: Arial, sans-serif; margin: 20px; }
              .header { font-size: 18px; font-weight: bold; margin-bottom: 20px; }
              .item { margin: 5px 0; }
              .total { font-weight: bold; margin-top: 20px; }
            </style>
          </head>
          <body>
            <pre>${printContent}</pre>
          </body>
        </html>
      `);
      printWindow.document.close();
      printWindow.print();
    }
  };

  const totalCost = shoppingList.reduce((sum, item) => sum + item.totalCost, 0);

  return (
    <Paper sx={{ p: 3 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h5">Список покупок</Typography>
        {shoppingList.length > 0 && (
          <Tooltip title="Распечатать список">
            <IconButton onClick={handlePrint} color="primary">
              <PrintIcon />
            </IconButton>
          </Tooltip>
        )}
      </Box>

      {/* Выбор блюд */}
      <Box sx={{ mb: 3 }}>
        <Typography variant="h6" gutterBottom>Выберите блюда:</Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
          {dishes.map(dish => (
            <Chip
              key={dish.id}
              label={dish.name}
              onClick={() => handleDishToggle(dish.id)}
              color={selectedDishes.includes(dish.id) ? 'primary' : 'default'}
              variant={selectedDishes.includes(dish.id) ? 'filled' : 'outlined'}
              clickable
            />
          ))}
        </Box>
      </Box>

      {shoppingList.length > 0 && (
        <>
          <Divider sx={{ my: 2 }} />
          
          {/* Список ингредиентов */}
          <Typography variant="h6" gutterBottom>
            Ингредиенты для покупки:
          </Typography>
          
          <TableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell padding="checkbox">
                    <Checkbox
                      checked={checkedItems.size === shoppingList.length}
                      indeterminate={checkedItems.size > 0 && checkedItems.size < shoppingList.length}
                      onChange={() => {
                        if (checkedItems.size === shoppingList.length) {
                          setCheckedItems(new Set());
                        } else {
                          setCheckedItems(new Set(shoppingList.map(item => item.ingredientId)));
                        }
                      }}
                    />
                  </TableCell>
                  <TableCell>Ингредиент</TableCell>
                  <TableCell align="right">Количество</TableCell>
                  <TableCell align="right">Цена за ед. (zł)</TableCell>
                  <TableCell align="right">Стоимость (zł)</TableCell>
                  <TableCell>Блюда</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {shoppingList.map(item => (
                  <TableRow key={item.ingredientId}>
                    <TableCell padding="checkbox">
                      <Checkbox
                        checked={checkedItems.has(item.ingredientId)}
                        onChange={() => handleItemToggle(item.ingredientId)}
                      />
                    </TableCell>
                    <TableCell>{item.ingredient.name}</TableCell>
                    <TableCell align="right">
                      {item.totalQuantity} {item.unit}
                    </TableCell>
                    <TableCell align="right">
                      {item.ingredient.pricePerUnit} zł
                    </TableCell>
                    <TableCell align="right">
                      {item.totalCost.toFixed(2)} zł
                    </TableCell>
                    <TableCell>
                      <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                        {item.dishes.map(dishName => (
                          <Chip key={dishName} label={dishName} size="small" variant="outlined" />
                        ))}
                      </Box>
                    </TableCell>
                  </TableRow>
                ))}
                <TableRow sx={{ backgroundColor: 'grey.100' }}>
                  <TableCell colSpan={4}>
                    <Typography variant="subtitle2">ИТОГО:</Typography>
                  </TableCell>
                  <TableCell align="right">
                    <Typography variant="subtitle2">{totalCost.toFixed(2)} zł</Typography>
                  </TableCell>
                  <TableCell />
                </TableRow>
              </TableBody>
            </Table>
          </TableContainer>
        </>
      )}

      {selectedDishes.length === 0 && (
        <Box sx={{ textAlign: 'center', py: 4 }}>
          <Typography variant="body1" color="text.secondary">
            Выберите блюда для создания списка покупок
          </Typography>
        </Box>
      )}
    </Paper>
  );
};
